  @type row_report :: %{
          required(:name) => binary(),
          required(:key_algorithm) => binary(),
          required(:verifiable) => boolean()
        }

  @type report :: %{
          required(:linked_crypto) => [{binary(), non_neg_integer(), binary()}],
          required(:algorithms) => [row_report()]
        }

  @doc """
  One verifiable verdict per registry row plus the linked crypto library.

  The verdict is per key algorithm (mixed-algorithm key sets are legal, so a
  single boolean could not answer for a whole registry). Each verdict derives
  from the pinned known-answer vector actually being verified, gated on the
  runtime's declared public-key algorithms.
  """
  @spec report() :: report()
  def report do
    %{
      linked_crypto: :crypto.info_lib(),
      algorithms:
        Enum.map(Algorithm.registry(), fn row ->
          %{
            name: row.name,
            key_algorithm: row.key_algorithm,
            verifiable: kat_verifies?(row.key_algorithm)
          }
        end)
    }
  end

  @doc """
  Whether the runtime declares support for one registry key algorithm.

  The Ed25519 key algorithm needs both the `:eddsa` public-key operation and
  the `:ed25519` curve declared; each ML-DSA parameterization needs its own
  atom. The declared lists are injectable so the decision boundary is testable
  as data; production reads them live.
  """
  @spec declared?(term(), [atom()] | nil, [atom()] | nil) :: boolean()
  def declared?(key_algorithm, public_keys \\ nil, curves \\ nil)

  def declared?("Ed25519", public_keys, curves) do
    :eddsa in declared_public_keys(public_keys) and :ed25519 in declared_curves(curves)
  end

  def declared?("ML-DSA-44", public_keys, _curves), do: :mldsa44 in declared_public_keys(public_keys)
  def declared?("ML-DSA-65", public_keys, _curves), do: :mldsa65 in declared_public_keys(public_keys)
  def declared?("ML-DSA-87", public_keys, _curves), do: :mldsa87 in declared_public_keys(public_keys)
  def declared?(_key_algorithm, _public_keys, _curves), do: false

  @doc """
  Whether the pinned known-answer vector for one key algorithm verifies.

  Declaration-gated: an undeclared algorithm short-circuits to false without
  invoking crypto, so the probe is safe on limited substrates. The gate is
  injectable for the same reason as `declared?/3`.
  """
  @spec kat_verifies?(term(), boolean() | nil) :: boolean()
  def kat_verifies?(key_algorithm, declared \\ nil)

  def kat_verifies?(key_algorithm, declared) when is_map_key(@known_answers, key_algorithm) do
    decided = if is_nil(declared), do: declared?(key_algorithm), else: declared
    decided and known_answer_verifies(key_algorithm)
  end

  def kat_verifies?(_key_algorithm, _declared), do: false

  defp known_answer_verifies("Ed25519") do
    %{public_key: public_key, signature: signature} = @known_answers["Ed25519"]

    :crypto.verify(:eddsa, :none, @known_answer_message, signature, [public_key, :ed25519])
  end

  defp known_answer_verifies("ML-DSA-44") do
    :crypto.verify(
      :mldsa44,
      :none,
      @known_answer_message,
      @known_answers["ML-DSA-44"].signature,
      @known_answers["ML-DSA-44"].public_key
    )
  end

  defp known_answer_verifies("ML-DSA-65") do
    :crypto.verify(
      :mldsa65,
      :none,
      @known_answer_message,
      @known_answers["ML-DSA-65"].signature,
      @known_answers["ML-DSA-65"].public_key
    )
  end

  defp known_answer_verifies("ML-DSA-87") do
    :crypto.verify(
      :mldsa87,
      :none,
      @known_answer_message,
      @known_answers["ML-DSA-87"].signature,
      @known_answers["ML-DSA-87"].public_key
    )
  end

  defp declared_public_keys(nil), do: :crypto.supports(:public_keys)
  defp declared_public_keys(list) when is_list(list), do: list

  defp declared_curves(nil), do: :crypto.supports(:curves)
  defp declared_curves(list) when is_list(list), do: list
end
